import Testing

@Suite struct FeedViewModelTests {
    @Test func loadsPosts() async throws {
        let model = await FeedViewModel(api: FakeFeedAPI(result: .success(Post.samples)))
        await model.refresh()
        guard case .loaded(let posts) = await model.state else {
            Issue.record("expected loaded"); return
        }
        #expect(posts.count == Post.samples.count)
    }

    @Test(arguments: [(1999, "$19.99"), (0, "$0.00"), (100_000, "$1,000.00")])
    func formatsCents(cents: Int, expected: String) {
        #expect(PriceFormatter(locale: .init(identifier: "en_US")).string(cents: cents) == expected)
    }
}
